@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;1,400;1,600&family=DM+Sans:wght@300;400;500&family=DM+Mono:wght@400&display=swap');

:root {
  --cream: #f5f0e8;
  --warm-white: #faf7f2;
  --gold: #c9963a;
  --gold-light: #e8b96a;
  --bg: #16120e;
  --bg2: #1f1a14;
  --bg3: #2a231a;
  --red: #c0392b;
  --red-soft: #e74c3c;
  --muted: rgba(245,240,232,0.45);
  --border: rgba(201,150,58,0.25);
}

/* ── BASE ── */
.reveal,
.reveal .slides section {
  background: var(--bg);
  color: var(--cream);
  font-family: 'DM Sans', sans-serif;
  font-weight: 300;
}

.reveal h1, .reveal h2, .reveal h3 {
  font-family: 'Playfair Display', Georgia, serif;
  color: var(--cream);
  font-weight: 700;
  letter-spacing: -0.01em;
  line-height: 1.15;
}

.reveal h1 { font-size: 2.6em; }
.reveal h2 {
  font-size: 1.7em;
  border-bottom: 1px solid var(--border);
  padding-bottom: 0.35em;
  margin-bottom: 0.8em;
}

.reveal p, .reveal li {
  font-weight: 300;
  line-height: 1.75;
  color: var(--cream);
  opacity: 0.9;
}

.reveal .slide-number {
  font-family: 'DM Mono', monospace;
  font-size: 0.65em;
  color: var(--gold);
  opacity: 0.6;
  bottom: 18px;
  right: 24px;
}

.reveal .footer {
  font-family: 'DM Mono', monospace;
  font-size: 0.6em;
  color: var(--muted);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* ── TITLE SLIDE ── */
.title-wrap {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 80vh;
  padding: 0 3em;
  position: relative;
}

.title-eyebrow {
  font-family: 'DM Mono', monospace;
  font-size: 0.65em;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 1.2em;
}

.title-main {
  font-family: 'Playfair Display', serif;
  font-size: 3.8em;
  font-weight: 700;
  line-height: 1.05;
  color: var(--warm-white);
  margin: 0 0 0.15em 0;
}

.title-main em {
  font-style: italic;
  color: var(--gold-light);
}

.title-sub {
  font-family: 'DM Sans', sans-serif;
  font-size: 1em;
  font-weight: 300;
  color: var(--muted);
  letter-spacing: 0.06em;
  margin-bottom: 2.5em;
}

.title-rule {
  width: 60px;
  height: 2px;
  background: linear-gradient(90deg, var(--gold), transparent);
  margin-bottom: 2em;
}

.title-tags {
  display: flex;
  gap: 0.8em;
  flex-wrap: wrap;
}

.tag {
  display: inline-block;
  font-family: 'DM Mono', monospace;
  font-size: 0.6em;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border: 1px solid var(--border);
  color: var(--gold);
  padding: 0.35em 0.9em;
  border-radius: 2px;
}

/* ── PULL QUOTE ── */
.pull-quote {
  font-family: 'Playfair Display', serif;
  font-style: italic;
  font-size: 1.35em;
  line-height: 1.6;
  color: var(--warm-white);
  border-left: 3px solid var(--gold);
  padding: 0.6em 0 0.6em 1.2em;
  margin: 1.2em 0;
}

.pull-quote cite {
  display: block;
  font-family: 'DM Mono', monospace;
  font-size: 0.5em;
  font-style: normal;
  color: var(--gold);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-top: 0.8em;
}

/* ── STAT HIGHLIGHT ── */
.stat-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5em;
  margin: 1.2em 0;
}

.stat-box {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1.4em 1em;
  text-align: center;
}

.stat-num {
  font-family: 'Playfair Display', serif;
  font-size: 2.4em;
  font-weight: 700;
  color: var(--gold-light);
  line-height: 1;
}

.stat-label {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.72em;
  color: var(--muted);
  margin-top: 0.5em;
  line-height: 1.4;
  font-weight: 300;
}

/* ── PSYCHOLOGY FLOW ── */
.flow {
  display: flex;
  align-items: center;
  gap: 0;
  margin: 1.5em 0;
  flex-wrap: nowrap;
}

.flow-node {
  flex: 1;
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1em 0.8em;
  text-align: center;
}

.flow-icon {
  font-size: 1.6em;
  display: block;
  margin-bottom: 0.3em;
}

.flow-label {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.7em;
  font-weight: 500;
  color: var(--cream);
  display: block;
  letter-spacing: 0.04em;
}

.flow-desc {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.58em;
  color: var(--muted);
  display: block;
  margin-top: 0.3em;
  line-height: 1.4;
}

.flow-arrow {
  font-size: 1em;
  color: var(--gold);
  padding: 0 0.3em;
  flex-shrink: 0;
  opacity: 0.7;
}

/* ── TRIGGER CARDS ── */
.trigger-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.2em;
  margin: 1em 0;
}

.trigger-card {
  background: var(--bg2);
  border-radius: 6px;
  padding: 1.2em 1.4em;
  border-top: 3px solid var(--gold);
  position: relative;
}

.trigger-card.red { border-top-color: var(--red-soft); }
.trigger-card.green { border-top-color: #27ae60; }
.trigger-card.blue { border-top-color: #2980b9; }

.trigger-num {
  font-family: 'DM Mono', monospace;
  font-size: 0.6em;
  color: var(--gold);
  letter-spacing: 0.1em;
  margin-bottom: 0.4em;
}

.trigger-title {
  font-family: 'Playfair Display', serif;
  font-size: 1em;
  font-weight: 700;
  color: var(--warm-white);
  margin-bottom: 0.5em;
}

.trigger-body {
  font-size: 0.72em;
  color: var(--muted);
  line-height: 1.6;
}

.trigger-example {
  display: inline-block;
  font-family: 'DM Mono', monospace;
  font-size: 0.62em;
  background: var(--bg3);
  color: var(--gold-light);
  padding: 0.2em 0.6em;
  border-radius: 2px;
  margin-top: 0.6em;
}

/* ── BRAND EXAMPLES ── */
.brand-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.2em;
  margin: 1.2em 0;
}

.brand-card {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 1.2em;
}

.brand-name {
  font-family: 'Playfair Display', serif;
  font-size: 1em;
  font-weight: 700;
  color: var(--gold-light);
  margin-bottom: 0.6em;
}

.brand-tactic {
  font-size: 0.68em;
  color: var(--muted);
  line-height: 1.6;
}

.brand-quote {
  font-family: 'DM Mono', monospace;
  font-size: 0.6em;
  color: var(--cream);
  background: var(--bg3);
  padding: 0.4em 0.7em;
  border-radius: 3px;
  margin-top: 0.7em;
  display: block;
  border-left: 2px solid var(--red-soft);
}

/* ── BALANCE SCALE ── */
.balance {
  display: grid;
  grid-template-columns: 1fr 60px 1fr;
  gap: 1em;
  align-items: start;
  margin: 1.2em 0;
}

.balance-side {
  background: var(--bg2);
  border-radius: 6px;
  padding: 1.2em;
}

.balance-label {
  font-family: 'DM Mono', monospace;
  font-size: 0.6em;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-bottom: 0.8em;
}

.balance-label.good { color: #27ae60; }
.balance-label.bad { color: var(--red-soft); }

.balance-mid {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5em;
  padding-top: 1.2em;
  color: var(--gold);
}

.balance-item {
  font-size: 0.7em;
  color: var(--cream);
  opacity: 0.85;
  padding: 0.35em 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  line-height: 1.4;
}

/* ── ETHICS FRAMEWORK ── */
.ethics-row {
  display: flex;
  flex-direction: column;
  gap: 0.8em;
  margin: 1em 0;
}

.ethics-item {
  display: flex;
  align-items: flex-start;
  gap: 1em;
  background: var(--bg2);
  border-radius: 4px;
  padding: 0.9em 1.1em;
  border-left: 3px solid var(--gold);
}

.ethics-icon {
  font-size: 1.2em;
  flex-shrink: 0;
  margin-top: 0.1em;
}

.ethics-text strong {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.8em;
  font-weight: 500;
  color: var(--warm-white);
  display: block;
  margin-bottom: 0.2em;
}

.ethics-text span {
  font-size: 0.68em;
  color: var(--muted);
  line-height: 1.5;
}

/* ── SUMMARY TABLE ── */
.reveal table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.78em;
  margin: 1em 0;
}

.reveal table th {
  font-family: 'DM Mono', monospace;
  font-size: 0.75em;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gold);
  border-bottom: 1px solid var(--border);
  padding: 0.7em 0.8em;
  text-align: left;
  background: transparent;
}

.reveal table td {
  padding: 0.75em 0.8em;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  color: var(--cream);
  opacity: 0.88;
  vertical-align: top;
  background: transparent;
}

.reveal table tr:hover td {
  background: rgba(201,150,58,0.05);
}

/* ── MISC ── */
.mono-label {
  font-family: 'DM Mono', monospace;
  font-size: 0.6em;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gold);
  display: block;
  margin-bottom: 0.6em;
}

.reveal blockquote {
  background: var(--bg2);
  border-left: 3px solid var(--gold);
  padding: 0.8em 1.2em;
  font-style: italic;
  color: var(--cream);
  margin: 1em 0;
  border-radius: 0 4px 4px 0;
}

hr.gold {
  border: none;
  border-top: 1px solid var(--border);
  margin: 1.2em 0;
}

